import { Empty } from '../entities/empty.js'
import { ConflictError } from '../errors.js'
import { Prisma } from '../generated/prisma/client.js'
import type { Page } from '../paging.js'

/** Where empties rows are kept. Services depend only on this interface. */
export interface EmptyRepository {
  findById(id: number): Promise<Empty | null>
  list(offset?: number, limit?: number): Promise<Page<Empty>>
  insert(entity: Empty): Promise<Empty>
  update(entity: Empty): Promise<Empty>
  delete(entity: Empty): Promise<void>
}

/** The key of a row, as a list of its key values. */
function keyOf(row: Empty): unknown[] {
  return [row.id]
}

/** Orders two keys value by value. */
function compareKeys(a: unknown[], b: unknown[]): number {
  for (let index = 0; index < a.length; index++) {
    const x = a[index] as number | string
    const y = b[index] as number | string
    if (x < y) return -1
    if (x > y) return 1
  }
  return 0
}

/** The Empty of a row Prisma read. */
function toEntity(row: Prisma.EmptyModel): Empty {
  return Object.assign(new Empty(), {
    id: Number(row.id),
    note: row.note,
  })
}

/** The values of a new row; those left undefined take the database's default. */
function createData(entity: Empty): Prisma.EmptyUncheckedCreateInput {
  return {
    id: entity.id,
    note: entity.note,
  }
}

/** The values a change writes: not the key, nor what the database fills. */
function updateData(entity: Empty): Prisma.EmptyUncheckedUpdateManyInput {
  return {
    note: entity.note,
  }
}

/** Keeps empties rows in the database, through a Prisma client. It never commits: the transaction belongs to the client it was given. */
export class SqlEmptyRepository implements EmptyRepository {
  constructor(private readonly db: Prisma.TransactionClient) {}

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Empty | null> {
    const row = await this.db.empty.findFirst({ where: { id } })
    return row === null ? null : toEntity(row)
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
  async list(offset: number = 0, limit: number = 50): Promise<Page<Empty>> {
    const rows = await this.db.empty.findMany({ orderBy: { id: 'asc' }, skip: offset, take: limit })
    const total = await this.db.empty.count()
    return { items: rows.map(toEntity), total, offset, limit }
  }

  /** Stores a new row; the values the database fills are read back. */
  async insert(entity: Empty): Promise<Empty> {
    try {
      return Object.assign(entity, toEntity(await this.db.empty.create({ data: createData(entity) })))
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) throw new ConflictError('Empty', `the database refused the change: ${error.message}`)
      throw error
    }
  }

  /** Stores the changes made to a row read from this repository. */
  async update(entity: Empty): Promise<Empty> {
    try {
      await this.db.empty.updateMany({ where: { id: entity.id }, data: updateData(entity) })
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) throw new ConflictError('Empty', `the database refused the change: ${error.message}`)
      throw error
    }
    return entity
  }

  /** Removes a row read from this repository. */
  async delete(entity: Empty): Promise<void> {
    try {
      await this.db.empty.deleteMany({ where: { id: entity.id } })
    } catch (error) {
      if (error instanceof Prisma.PrismaClientKnownRequestError) throw new ConflictError('Empty', `the database refused the change: ${error.message}`)
      throw error
    }
  }
}

/** Keeps empties rows in memory, for tests and for trying the services without a database. */
export class MemoryEmptyRepository implements EmptyRepository {
  private readonly rows = new Map<string, Empty>()
  private nextId = 1

  private visible(): Empty[] {
    return [...this.rows.values()].filter((row) => true).sort((a, b) => compareKeys(keyOf(a), keyOf(b)))
  }

  /** The row with this primary key, or null. */
  async findById(id: number): Promise<Empty | null> {
    return this.visible().find((row) => row.id === id) ?? null
  }

  /** At most `limit` rows from `offset`, by primary key, and how many there are. */
