      const value = values.opens
      if (value == null) {
        if (creating || 'opens' in values) errors.push({ field: 'opens', message: 'is required' })
      }
    }
    {
      const value = values.at
      if (value == null) {
        if (creating || 'at' in values) errors.push({ field: 'at', message: 'is required' })
      }
    }
    {
      const value = values.bin
      if (value == null) {
        if (creating || 'bin' in values) errors.push({ field: 'bin', message: 'is required' })
      }
    }
    {
      const value = values.data
      if (value == null) {
        if (creating || 'data' in values) errors.push({ field: 'data', message: 'is required' })
      }
    }
    {
      const value = values.feeling
      if (value == null) {
        if (creating || 'feeling' in values) errors.push({ field: 'feeling', message: 'is required' })
      }
    }
    {
      const value = values.code
      if (value == null) {
        if (creating || 'code' in values) errors.push({ field: 'code', message: 'is required' })
      } else {
        if (typeof value === 'string' && value.length > 5) errors.push({ field: 'code', message: 'is longer than 5 characters' })
      }
    }
    if (errors.length > 0) throw new ValidationFailedError('Thing', errors)
  }

  /** Every check before a write: the values, the rows they point to, the unique values. */
  private async check(uow: UnitOfWork, values: Partial<Record<string, unknown>>, current: Thing | null): Promise<void> {
    await this.validate(uow, values, current)
  }

  /** The Thing with this key; NotFoundError when there is none. */
  private async find(uow: UnitOfWork, id: string): Promise<Thing> {
    const entity = await uow.things.findById(id)
    if (entity === null) throw new NotFoundError('Thing', id)
    return entity
  }

  /** Stores a new Thing after checking it. */
  async createThing(thing: Thing): Promise<Thing> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries([...FIELDS].map((field) => [field, (thing as unknown as Record<string, unknown>)[field]]))
    return this.uow.transaction(async (uow) => {
      await this.check(uow, values, null)
      const created = await uow.things.insert(thing)
      return created
    })
  }

  /** The Thing with this key; NotFoundError when there is none. */
  async getThing(id: string): Promise<Thing> {
    return await this.find(this.uow, id)
  }

  /** A page of things, by primary key. */
  async listThings(offset = 0, limit = 50): Promise<Page<Thing>> {
    return this.uow.things.list(offset, limit)
  }

  /** Changes the given values of a Thing. */
  async updateThing(id: string, changes: Partial<Thing>): Promise<Thing> {
    const values: Partial<Record<string, unknown>> = Object.fromEntries(Object.entries(changes).filter(([, value]) => value !== undefined))
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await this.check(uow, values, current)
      Object.assign(current, values)
      const updated = await uow.things.update(current)
      return updated
    })
  }

  /** Deletes a Thing. */
  async deleteThing(id: string): Promise<void> {
    return this.uow.transaction(async (uow) => {
      const current = await this.find(uow, id)
      await uow.things.delete(current)
    })
  }
}

